const escapeHtml = (value) => String(value).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");

function renderVisual(section, index) {
  const visual = visuals[`${section}-${index}`];
  if (!visual) return "";
  return `<figure class="concept-visual" aria-label="${escapeHtml(visual[0])}"><figcaption>${escapeHtml(visual[0])}</figcaption><div>${visual[1].map((item, i) => `<span>${escapeHtml(item)}</span>${i < visual[1].length - 1 ? '<b aria-hidden="true">→</b>' : ""}`).join("")}</div></figure>`;
}

function renderActivity(stage, index, section) {
  const override = activities[`${section}-${index}`];
  const feedback = escapeHtml(stage[6]);
  if (!override) return `<form class="activity" data-type="choice" data-answer='["${stage[5]}"]'><fieldset><legend>${escapeHtml(stage[3])}</legend>${stage[4].map((option, i) => `<label class="option"><input type="radio" name="q-${index}" value="${i}"><span>${escapeHtml(option)}</span></label>`).join("")}</fieldset><button class="button" type="submit">Comprobar respuesta</button><p class="feedback" aria-live="polite" data-success="${feedback}"></p></form>`;
  if (override.type === "multi") return `<form class="activity" data-type="multi" data-answer='${JSON.stringify(override.answer)}'><fieldset><legend>${escapeHtml(override.prompt)}</legend><p class="instruction">Puede existir más de una respuesta correcta.</p>${override.options.map((option, i) => `<label class="option"><input type="checkbox" value="${i}"><span>${escapeHtml(option)}</span></label>`).join("")}</fieldset><button class="button" type="submit">Validar selección</button><p class="feedback" aria-live="polite" data-success="${feedback}"></p></form>`;
  if (override.type === "order") {
    const options = override.items.map(([value, label]) => `<option value="${value}">${escapeHtml(label)}</option>`).join("");
    return `<form class="activity" data-type="order" data-answer='${JSON.stringify(override.answer)}'><fieldset><legend>${escapeHtml(override.prompt)}</legend><p class="instruction">Selecciona un elemento diferente en cada posición.</p><div class="order-grid">${override.items.map((_, i) => `<label><span>Posición ${i + 1}</span><select><option value="">Seleccionar…</option>${options}</select></label>`).join("")}</div></fieldset><button class="button" type="submit">Validar orden</button><p class="feedback" aria-live="polite" data-success="${feedback}"></p></form>`;
  }
  const options = override.choices.map(([value, label]) => `<option value="${value}">${escapeHtml(label)}</option>`).join("");
  return `<form class="activity" data-type="${override.type}" data-answer='${JSON.stringify(override.answer)}'><fieldset><legend>${escapeHtml(override.prompt)}</legend><div class="relation-grid">${override.rows.map(([label]) => `<label><span>${escapeHtml(label)}</span><select><option value="">Seleccionar…</option>${options}</select></label>`).join("")}</div></fieldset><button class="button" type="submit">Validar relaciones</button><p class="feedback" aria-live="polite" data-success="${feedback}"></p></form>`;
}

