const catalogEnhancementCss = `.unit-actions{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:.6rem}.unit-download,.fullscreen-button{display:inline-flex;align-items:center;justify-content:center;min-height:48px;margin:0;padding:.75rem 1rem;border:2px solid #fff;border-radius:10px;font:inherit;font-weight:850;cursor:pointer}.fullscreen-button{gap:.4rem;color:#fff;background:transparent}.unit-download:hover{background:#f4f1ff}.fullscreen-button:hover{background:#ffffff18}.fullscreen-button[aria-pressed="true"]{color:var(--purple);background:#fff}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}button:focus-visible{outline:3px solid var(--pink);outline-offset:3px}`;

const catalogApp = `const fullscreenButton=document.querySelector("#fullscreen-toggle");const fullscreenLabel=document.querySelector("#fullscreen-label");const fullscreenStatus=document.querySelector("#fullscreen-status");const page=document.documentElement;const enterFullscreen=page.requestFullscreen||page.webkitRequestFullscreen;const exitFullscreen=document.exitFullscreen||document.webkitExitFullscreen;const isFullscreen=()=>Boolean(document.fullscreenElement||document.webkitFullscreenElement);function updateFullscreenControl(){const active=isFullscreen();fullscreenButton.setAttribute("aria-pressed",String(active));fullscreenLabel.textContent=active?"Salir de pantalla completa":"Pantalla completa"}if(!enterFullscreen||!exitFullscreen){fullscreenButton.hidden=true}else{fullscreenButton.addEventListener("click",async()=>{try{if(isFullscreen()){await exitFullscreen.call(document)}else{await enterFullscreen.call(page)}}catch{fullscreenStatus.textContent="El navegador no permitió cambiar al modo de pantalla completa."}});document.addEventListener("fullscreenchange",updateFullscreenControl);document.addEventListener("webkitfullscreenchange",updateFullscreenControl);updateFullscreenControl()}`;

function renderCatalog() {
  const cards = sections.map(section => `<article class="section-card"><span class="number">${section.number}</span><p class="eyebrow">${section.duration}</p><h2>${escapeHtml(section.title)}</h2><p>${escapeHtml(section.result)}</p><div class="actions"><a class="primary" href="seccion-${section.number}-${section.slug}/dist/index.html">Abrir sección</a><a href="../publicables/Seccion-${section.number}-${section.slug}.zip" download>Descargar ZIP</a></div></article>`).join("");
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Catálogo de la Unidad 2 Organización celular"><title>Unidad 2 — Organización celular</title><link rel="stylesheet" href="catalogo.css"></head><body><a class="skip-link" href="#catalogo">Saltar al catálogo</a><header class="hero"><div class="shell hero-grid"><img src="seccion-01-la-celula-y-sus-componentes-comunes/dist/assets/brand/ctev-universidad-cartagena.jpeg" alt="CTEV, Centro Tecnológico para la Formación Virtual y a Distancia, Universidad de Cartagena"><div><p class="eyebrow">Seguridad y Salud en el Trabajo a Distancia · Biología</p><h1>Unidad 2 · Organización celular</h1><p>Seis experiencias para comparar tipos celulares, diferenciar virus y bacterias, comprender la cooperación de los orgánulos y transferir el conocimiento al análisis laboral.</p><a class="unit-download" href="../publicables/Unidad-02-Organizacion-celular-completa.zip" download>Descargar la unidad completa</a></div></div></header><main id="catalogo" class="shell"><section class="orientation"><div><p class="eyebrow">Cómo utilizar esta ruta</p><h2>Seis secciones complementarias</h2><p>Puedes abrir cualquier sección de forma independiente. La navegación interna es libre y el avance solo se registra al resolver correctamente cada actividad.</p></div><ul><li>Lecturas académicas contextualizadas.</li><li>Actividades de selección, ordenamiento, relación y clasificación.</li><li>Insignia individual al alcanzar el 100 % validado.</li></ul></section><section class="section-grid" aria-label="Secciones de la Unidad 2">${cards}</section></main><footer><div class="shell">Universidad de Cartagena · Centro Tecnológico para la Formación Virtual y a Distancia</div></footer></body></html>`;
}

function renderEnhancedCatalog() {
  return renderCatalog()
    .replace(
      '<a class="unit-download" href="../publicables/Unidad-02-Organizacion-celular-completa.zip" download>Descargar la unidad completa</a>',
      '<div class="unit-actions"><a class="unit-download" href="../publicables/Unidad-02-Organizacion-celular-completa.zip" download>Descargar la unidad completa</a><button class="fullscreen-button" id="fullscreen-toggle" type="button" aria-pressed="false"><span aria-hidden="true">⛶</span> <span id="fullscreen-label">Pantalla completa</span></button></div><p id="fullscreen-status" class="sr-only" aria-live="polite"></p>'
    )
    .replace('</body>', '<script src="catalogo.js"></script></body>');
}

for (const section of sections) {
  const folder = path.join(unit, "implementacion", `seccion-${section.number}-${section.slug}`);
  const dist = path.join(folder, "dist");
  fs.mkdirSync(dist, { recursive: true });
  fs.cpSync(sourceAssets, path.join(dist, "assets"), { recursive: true });
  fs.writeFileSync(path.join(dist, "index.html"), renderSection(section), "utf8");
  fs.writeFileSync(path.join(dist, "styles.css"), css, "utf8");
  fs.writeFileSync(path.join(dist, "app.js"), app, "utf8");
  fs.writeFileSync(path.join(folder, "README.md"), `# Sección ${section.number} — ${section.title}\n\n- Duración: ${section.duration}.\n- Ocho etapas con navegación libre.\n- Progreso mediante respuestas correctas.\n- Actividades variadas e insignia al 100 %.\n- Entrada: \`dist/index.html\`.\n`, "utf8");
}

fs.writeFileSync(path.join(unit, "implementacion", "index.html"), renderEnhancedCatalog(), "utf8");
fs.writeFileSync(path.join(unit, "implementacion", "catalogo.css"), catalogCss + catalogEnhancementCss, "utf8");
fs.writeFileSync(path.join(unit, "implementacion", "catalogo.js"), catalogApp, "utf8");
console.log(`Generadas ${sections.length} secciones de la Unidad 2`);
